:root {
  --ink: #1e2942;
  --muted: #6f7890;
  --paper: #fffdf9;
  --line: #e4e7ee;
  --navy: #253b67;
  --navy-soft: #edf2fb;
  --coral: #ef6d5d;
  --coral-soft: #fff0ed;
  --blue: #5a89d8;
  --blue-soft: #edf4ff;
  --gold: #d7a43b;
  --gold-soft: #fff7e5;
  --green: #31866c;
  --green-soft: #e9f7f1;
  --white: #ffffff;
}

.results-card {
  box-sizing: border-box;
  width: 500px;
  min-height: 278px;
  padding: 15px;
  display: grid;
  gap: 10px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
  color: var(--ink);
}

.card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 2px;
}

.head-copy {
  display: flex;
  align-items: baseline;
  gap: 9px;
}

.eyebrow {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

h1,
h2,
p {
  margin: 0;
}

h1 {
  font-size: 18px;
  line-height: 1;
  letter-spacing: -0.03em;
}

.live {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  border-radius: 999px;
  background: var(--coral-soft);
  color: var(--coral);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.live-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--coral);
}

.race {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 13px;
}

.race-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  background: var(--navy);
  color: var(--white);
}

.race-top h2 {
  font-size: 14px;
  line-height: 1.1;
}

.race-top p {
  margin-top: 3px;
  color: var(--navy-soft);
  font-size: 10px;
}

.call-status {
  padding: 4px 6px;
  border: 1px solid var(--coral);
  border-radius: 5px;
  color: var(--coral);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.05em;
}

.results {
  margin: 0;
  padding: 0;
  list-style: none;
}

.result {
  min-height: 35px;
  padding: 6px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--line);
}

.result.leader {
  background: var(--coral-soft);
  border-left: 4px solid var(--coral);
  padding-left: 8px;
}

.candidate {
  display: flex;
  align-items: center;
  gap: 8px;
}

.avatar {
  width: 25px;
  height: 25px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  font-size: 9px;
  font-weight: 800;
}

.avatar.coral {
  background: var(--coral);
  color: var(--white);
}

.avatar.blue {
  background: var(--blue-soft);
  color: var(--blue);
}

.avatar.gold {
  background: var(--gold-soft);
  color: var(--gold);
}

.candidate-name,
.score {
  display: flex;
  flex-direction: column;
}

.candidate-name strong,
.score strong {
  font-size: 12px;
  line-height: 1.15;
}

.candidate-name small,
.score small {
  margin-top: 2px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1;
}

.score {
  align-items: flex-end;
}

.turnout {
  padding: 8px 12px;
  display: flex;
  align-items: center;
  gap: 9px;
  background: var(--navy-soft);
}

.turnout-label {
  min-width: 83px;
  color: var(--muted);
  font-size: 10px;
}

.turnout-label strong {
  color: var(--ink);
}

.meter {
  height: 6px;
  flex: 1;
  overflow: hidden;
  border-radius: 999px;
  background: var(--line);
}

.meter span {
  display: block;
  width: 68%;
  height: 100%;
  border-radius: inherit;
  background: var(--green);
}

.ballots {
  color: var(--navy);
  font-size: 10px;
  font-weight: 700;
}

.card-foot {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 2px;
  color: var(--muted);
  font-size: 10px;
}

.margin {
  padding: 4px 7px;
  border-radius: 5px;
  background: var(--green-soft);
  color: var(--green);
  font-weight: 800;
}
